const tabId = 103795220;

async function getGamesForMonth(monthStr) {
  const url = `https://npb.jp/games/2026/schedule_${monthStr}_detail.html`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 15000 });

  return await browserjs(tabId, () => {
    const rows = Array.from(document.querySelectorAll('table tbody tr'));
    const games = [];
    let currentDate = "";

    for (const tr of rows) {
      const dateTh = tr.querySelector('th.date') || tr.querySelector('th');
      if (dateTh && dateTh.textContent.trim()) {
        currentDate = dateTh.textContent.trim();
      }

      const matchTd = tr.querySelector('td.match');
      const infoTd = tr.querySelector('td.info');
      const commentTd = tr.querySelector('td.comment');

      if (matchTd && infoTd) {
        const match = matchTd.textContent.trim().replace(/\s+/g, ' ');
        const info = infoTd.textContent.trim().replace(/\s+/g, ' ');
        const comment = commentTd ? commentTd.textContent.trim().replace(/\s+/g, ' ') : '';
        games.push({
          date: currentDate,
          match,
          info,
          comment
        });
      }
    }
    return games;
  });
}

