async function parseMonth(monthStr) {
  const url = `https://npb.jp/games/2026/schedule_${monthStr}_detail.html`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 15000 });

  return await browserjs(tabId, () => {
    const rows = Array.from(document.querySelectorAll('table tbody tr, table tr'));
    const games = [];
    let currentDate = "";

    for (const tr of rows) {
      const th = tr.querySelector('th');
      if (th && th.textContent.trim() && !th.textContent.includes('月日')) {
        currentDate = th.textContent.trim();
      }

      const tds = Array.from(tr.querySelectorAll('td'));
      if (tds.length >= 2) {
        const team1 = tds[0].querySelector('.team1')?.textContent?.trim() || "";
        const team2 = tds[0].querySelector('.team2')?.textContent?.trim() || "";
        const place = tds[1].querySelector('.place')?.textContent?.trim().replace(/\s+/g, '') || "";
        const time = tds[1].querySelector('.time')?.textContent?.trim() || "";
        const comment = tds[2]?.textContent?.trim() || "";

        if (place && team1 && team2) {
          games.push({
            date: currentDate,
            homeTeam: team1, // In NPB schedule: team1 is home team? Wait, let's verify team1 vs team2!
            awayTeam: team2,
            place,
            time,
            comment
          });
        }
      }
    }
    return games;
  });
}

