const rawGames = JSON.parse(await (await read("tmp://all_games.json")).text);

const STADIUMS = [
  "エスコンＦ",
  "楽天モバイル",
  "ベルーナドーム",
  "東京ドーム",
  "神宮",
  "ZOZOマリン",
  "横浜",
  "バンテリンドーム",
  "京セラD大阪",
  "甲子園",
  "マツダスタジアム",
  "みずほPayPay"
];

// Normalize dates: e.g. "6/2（火）" -> month: 6, day: 2, dateStr: "2026-06-02"
function parseDate(dStr) {
  const m = dStr.match(/(\d+)\/(\d+)/);
  if (!m) return null;
  const month = parseInt(m[1], 10);
  const day = parseInt(m[2], 10);
  const dateObj = new Date(2026, month - 1, day);
  const dayNum = Math.round(dateObj.getTime() / (1000 * 60 * 60 * 24));
  return {
    month,
    day,
    formatted: `2026-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`,
    dayNum,
    raw: dStr
  };
}

const cleanGames = [];
for (const g of rawGames) {
  if (!STADIUMS.includes(g.place)) continue;
  const pDate = parseDate(g.date);
  if (!pDate) continue;
  cleanGames.push({
    ...g,
    ...pDate
  });
}

console.log(`Clean games matching 12 stadiums: ${cleanGames.length}`);

// Group by date and stadium
const gamesByStadiumAndDate = {};
for (const s of STADIUMS) {
  gamesByStadiumAndDate[s] = {};
}
for (const g of cleanGames) {
  gamesByStadiumAndDate[g.place][g.formatted] = g;
}

// Let's find valid sequences of dates!
// We want: 12 distinct stadiums.
// Each game is on a separate date, OR max 1 game per day (a realistic trip has 1 game per day).
// Can have rest/travel days between games (e.g. 0, 1, or 2 rest days).
// Total trip length: say 12 to 20 days.
// Geographic order is critical for realism!
// A natural geographic path:
// ES CON FIELD (Hokkaido) -> Rakuten Mobile (Sendai) -> Kanto cluster (Tokyo Dome, Jingu, Belluna, ZOZO Marine, Yokohama in any order) -> Nagoya -> Kansai (Osaka, Koshien) -> Hiroshima -> Fukuoka.
// OR the reverse: Fukuoka -> Hiroshima -> Kansai (Osaka, Koshien) -> Nagoya -> Kanto cluster -> Sendai -> Hokkaido.

console.log("Sample games by stadium availability:");
for (const s of STADIUMS) {
  const dates = Object.keys(gamesByStadiumAndDate[s]);
  console.log(`${s}: ${dates.length} dates (e.g. ${dates.slice(0, 3).join(', ')} ... ${dates.slice(-2).join(', ')})`);
}

