const tabId = 103795220;
await tool.navigate({ tabId, url: "https://www.google.com/travel/flights?q=Flights%20from%20CTS%20to%20SDJ%20on%202026-06-24" });
await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 15000 });
// Wait a couple seconds for flight results to render
await new Promise(r => setTimeout(r, 4000));

const flightData = await browserjs(tabId, () => {
  const text = document.body.innerText;
  // Look for airlines, times, prices
  const priceMatches = text.match(/[$¥]\s?[\d,]+/g) || [];
  const airlines = ["Peach", "IBEX", "ANA", "JAL", "Skymark", "Air Do"];
  const foundAirlines = airlines.filter(a => text.includes(a));

  // Look for flight elements
  const cards = Array.from(document.querySelectorAll('li, div[role="listitem"]'))
    .map(el => el.innerText.replace(/\n+/g, ' | '))
    .filter(t => t.includes('CTS') || t.includes('SDJ') || t.includes('min') || t.includes('hr'));

  return {
    url: window.location.href,
    title: document.title,
    priceMatches: priceMatches.slice(0, 15),
    foundAirlines,
    sampleCards: cards.slice(0, 5)
  };
});

console.log(JSON.stringify(flightData, null, 2));

