const tabId = 103795220;

// Click the Done button in the dialog
await browserjs(tabId, () => {
  const dialog = document.querySelector('div[role="dialog"]');
  if (!dialog) return "no dialog";
  const buttons = Array.from(dialog.querySelectorAll('button'));
  const doneBtn = buttons.find(b => b.textContent.trim() === "Done");
  if (doneBtn) {
    doneBtn.click();
    return "clicked Done";
  }
  return "Done button not found";
});

await new Promise(r => setTimeout(r, 1000));

// Click the Search button
const searchRes = await browserjs(tabId, () => {
  const buttons = Array.from(document.querySelectorAll('button'));
  const searchBtn = buttons.find(b => b.textContent.trim() === "Search" || b.getAttribute('aria-label') === "Search");
  if (searchBtn) {
    searchBtn.click();
    return "clicked Search";
  }
  return "Search button not found";
});

