    const title = c.querySelector('[data-testid="title"]')?.textContent?.trim();
    const score = c.querySelector('[data-testid="review-score"]')?.textContent?.trim();
    const price = c.querySelector('[data-testid="price-and-discounted-price"]')?.textContent?.trim();
    const link = c.querySelector('a[data-testid="title-link"]')?.href;
    const distance = c.querySelector('[data-testid="distance"]')?.textContent?.trim();
    return { title, score, price, distance, link };
  });
});

