args.code:
const tabId = 103795413;
const fullText = await (await read("tmp://full_itinerary.txt")).text;

// Let's test writing to clipboard in browserjs
const clipOk = await browserjs(tabId, async (text) => {
  try {
    await navigator.clipboard.writeText(text);
    return { ok: true };
  } catch (e) {
    return { ok: false, error: e.toString() };
  }
}, fullText);

console.log("Clipboard write result:", clipOk);

if (clipOk.ok) {
  // Focus editor
  await tool.element_interact({ tabId, ref: "e366", operation: "click", value: null, target_ref: null });
  await new Promise(r => setTimeout(r, 400));

  // Paste
  console.log("Pasting...");
  await tool.press({ tabId, keys: "ControlOrMeta+v" });
  await new Promise(r => setTimeout(r, 3000));
} else {
  // If clipboard write is not permitted, insert in chunks of 2,000 chars
  console.log("Falling back to chunked insertion...");
  const chunkSize = 2000;
  for (let i = 0; i < fullText.length; i += chunkSize) {
    const chunk = fullText.slice(i, i + chunkSize);
    console.log(`Inserting chunk ${i} to ${i + chunk.length}...`);
    await tool.keyboard_insert_text({ tabId, text: chunk });
    await new Promise(r => setTimeout(r, 300));
  }
}

const shot = await browser.screenshot({ tabId });
console.log("Screenshot URI:", shot.image);

