const tabsToOpen = [
  // Hotels on Booking.com
  { url: "https://www.booking.com/hotel/jp/tokyo-dome-hotel.html", type: "Hotel", desc: "Tokyo Dome Hotel (Tokyo Dome)" },
  { url: "https://www.booking.com/hotel/jp/hoteruhiyuitutojia-zi-yuan.html", type: "Hotel", desc: "Hotel Hewitt Koshien (Hanshin Koshien Stadium)" },
  { url: "https://www.booking.com/hotel/jp/hilton-fukuoka-sea-hawk.html", type: "Hotel", desc: "Hilton Fukuoka Sea Hawk (Mizuho PayPay Dome Fukuoka)" },
  { url: "https://www.booking.com/hotel/jp/daiwa-roynet-yokohama-koen.html", type: "Hotel", desc: "Daiwa Roynet Hotel Yokohama-Koen (Yokohama Stadium)" },

  // Food spots
  { url: "https://www.ganso-yokocho.com/", type: "Food", desc: "Ganso Ramen Yokocho (Susukino Ramen Alley, Sapporo)" },
  { url: "https://www.houraiken.com/english/", type: "Food", desc: "Atsuta Horaiken (Nagoya Hitsumabushi / Charcoal Eel)" },
  { url: "https://nagataya-okonomi.biz/en/", type: "Food", desc: "Okonomiyaki Nagata-ya (Hiroshima Okonomiyaki)" },
  { url: "https://hakata-issou.com/", type: "Food", desc: "Hakata Isshin Ramen (Hakata Tonkotsu Ramen, Fukuoka)" }
];

const openedTabs = [];

for (const t of tabsToOpen) {
  console.log(`Opening tab: ${t.desc} (${t.url})...`);
  const res = await tool.tabs_create({ url: t.url });
  const newTabId = res.details.tabId;
  await tool.wait_for({ tabId: newTabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 15000 });
  await new Promise(r => setTimeout(r, 1500));
  const title = await browserjs(newTabId, () => document.title);
  const finalUrl = await browserjs(newTabId, () => window.location.href);
  openedTabs.push({ tabId: newTabId, type: t.type, desc: t.desc, title, finalUrl });
}

console.log("All tabs opened:", JSON.stringify(openedTabs, null, 2));

